/**
 * Planfix REST API constants.
 *
 * Planfix is per-account SaaS: every account is reachable at its own
 * `https://{account}.planfix.com/rest` origin, where `{account}` is the
 * subdomain the customer logs in at. There is no separate sandbox host — a
 * trial account is just another subdomain — so the base URL is built per
 * connection from `credentials.extra.account` (see `client.ts`).
 *
 * Auth is a static Bearer token generated by the primary account admin under
 * Account Management → API Access → REST API. There is no OAuth2
 * authorization-code flow and the token does not refresh.
 *
 * List methods are POSTs whose JSON body carries `{ offset, pageSize, fields }`.
 * `pageSize` is capped at 100; `fields` is a comma-separated allow-list of the
 * field names the response should include (Planfix returns only `id` by
 * default). List responses are enveloped as `{ result: "success", <coll>: [...] }`.
 *
 * Docs: https://help.planfix.com/restapidocs/ · https://planfix.com/help/REST_API
 */

/** Build the per-account REST base URL from the account subdomain or full origin. */
export function buildBaseUrl(account: string): string {
  const a = account.trim().replace(/\/+$/, '')
  // Accept a full origin (explicit host) as well as a bare subdomain.
  if (/^https?:\/\//i.test(a)) return `${a.replace(/\/rest$/i, '').replace(/\/+$/, '')}/rest`
  // A bare host ("acme.planfix.com") vs. a bare subdomain ("acme").
  if (a.includes('.')) return `https://${a.replace(/\/rest$/i, '')}/rest`
  return `https://${a}.planfix.com/rest`
}

/** Where the primary admin generates the REST API token. */
export const TOKEN_HELP_URL = 'https://planfix.com/help/REST_API_Introduction'

/** Default `pageSize` of Planfix list bodies ("default":100). */
export const DEFAULT_PAGE_SIZE = 100

/** Maximum `pageSize` of every Planfix list body ("maximum":100). */
export const MAX_PAGE_SIZE = 100

/**
 * System fields requested from list/get methods. Planfix returns only `id`
 * unless `fields` is supplied, so the adapter asks for the canonical-relevant
 * system fields explicitly, comma-delimited.
 */
export const TASK_FIELDS =
  'id,name,description,priority,status,type,project,parent,assignees,counterparty,startDateTime,endDateTime,dateTime,dateOfLastUpdate,overdue,closeToDeadLine'
export const PROJECT_FIELDS =
  'id,name,description,status,owner,parent,counterparty,startDate,endDate,overdue'
export const USER_FIELDS = 'id,name,midname,lastname,email,login,status,groups,role'
export const COMMENT_FIELDS =
  'id,dateTime,type,fromType,description,task,project,owner,recipients,isDeleted'
